-- Банк идей для свиданий: 160 идей, по 40 на категорию, на трёх языках.
--
-- Без алкоголя (может быть беременность), без дорогих покупок и без
-- выдуманных мест, цен и расстояний: в городе и в поездке - то, что
-- найдётся почти везде. «На расстоянии» - самая важная категория: пара
-- живёт порознь, и идеи для видеозвонка нужны чаще всего.
--
-- rank - порядок показа: категории перемешаны, чтобы колода не начиналась
-- с сорока домашних идей подряд. Свои идеи пары (rank пустой) - первыми.

on conflict (key) do update set
  category = excluded.category,
  title_ru = excluded.title_ru, title_en = excluded.title_en, title_kk = excluded.title_kk,
  hint_ru = excluded.hint_ru, hint_en = excluded.hint_en, hint_kk = excluded.hint_kk,
  rank = excluded.rank;

-- Напоминание о лекарстве - на «ты», как всё приложение
on conflict (key, lang) do update set value = excluded.value;
