insert into public.date_ideas (key, category, title_ru, title_en, title_kk, hint_ru, hint_en, hint_kk, rank) values
  ('home-paper-cranes', 'home', 'Сложить сто бумажных журавликов', 'Fold a hundred paper cranes', 'Қағаздан жүз тырна құрастыру', 'По десять за вечер, а потом нанизать их в гирлянду над кроватью.', 'Ten per evening, then string them into a garland over the bed.', 'Кешіне оннан жасап, бәрін жіпке тізіп, төсек үстіне іліп қойыңдар.', 2),
  ('home-pizza-from-scratch', 'home', 'Испечь пиццу с нуля', 'Bake pizza from scratch', 'Қамырынан бастап пицца пісіру', 'Замесить тесто вместе, а начинку собрать по своему вкусу на каждой половине.', 'Knead the dough together, then top your own halves however you like.', 'Қамырды бірге илеп, үстіне әрқайсысы өз жартысына қалағанын салсын.', 6),
  ('home-blanket-fort', 'home', 'Построить шалаш из пледов для кино', 'Build a blanket fort for movie night', 'Көрпеден лашық құрып, кино көру', 'Подушки, гирлянда, ноутбук внутри и правило: выходить только за чаем.', 'Pillows, fairy lights, a laptop inside, and one rule: leave only for tea.', 'Ішіне жастық, шамдар мен ноутбук апарып, тек шайға ғана шығуға келісіңдер.', 10),
  ('home-board-game-tournament', 'home', 'Устроить турнир по настольным играм', 'Hold a board game tournament', 'Үстел ойындарынан жарыс өткізу', 'Три игры, таблица очков на холодильнике, а приз за победу - выбор фильма.', 'Three games, a score sheet on the fridge, and the winner picks the movie.', 'Үш ойын, тоңазытқышта ұпай кестесі, ал жеңімпаз кешкі фильмді таңдайды.', 14),
  ('home-jigsaw-puzzle', 'home', 'Собрать пазл на тысячу деталей', 'Do a 1000-piece jigsaw puzzle', 'Мың бөлшекті пазл құрастыру', 'Поделить роли: кто-то собирает края, кто-то небо, а готовое повесить на стену.', 'Split the roles, edges for one and sky for the other, then hang it on the wall.', 'Біреуі шетін, екіншісі аспанын жинап, дайын суретті қабырғаға іліңдер.', 18),
  ('home-baursaks-for-neighbors', 'home', 'Нажарить баурсаков и угостить соседей', 'Fry baursaks and share with neighbors', 'Бауырсақ пісіріп, көршіге ауыз тигізу', 'Поставить тесто с утра, а горячие баурсаки разнести соседям к чаю.', 'Set the dough to rise in the morning and bring them hot to the neighbors for tea.', 'Қамырды таңертең ашытып, ыстық бауырсақты көршілерге шайға апарыңдар.', 22),
  ('home-manti-batch', 'home', 'Налепить мантов на неделю вперёд', 'Make a big batch of manti', 'Бір аптаға жететін манты түю', 'Половину приготовить сразу, а остальное заморозить на ленивые вечера.', 'Steam half right away and freeze the rest for lazy evenings.', 'Жартысын бірден буға пісіріп, қалғанын ерінетін кештерге мұздатып қойыңдар.', 26),
  ('home-slow-breakfast', 'home', 'Устроить долгий завтрак без спешки', 'Have a slow, unhurried breakfast', 'Асықпай ұзақ таңғы ас ішу', 'Сырники или блины, свежий чай и правило: никаких телефонов до полудня.', 'Pancakes, fresh tea, and one rule: no phones until noon.', 'Құймақ, жаңа демделген шай және бір шарт: түске дейін телефон ұстамау.', 30),
  ('home-spa-evening', 'home', 'Устроить домашний спа-вечер', 'Have a spa evening at home', 'Үйде спа-кеш ұйымдастыру', 'Маски для лица, ванночка для ног, спокойная музыка и массаж по очереди.', 'Face masks, a foot soak, calm music, and massages in turns.', 'Бетке маска, аяққа жылы ванна, баяу музыка және кезекпен массаж.', 34),
  ('home-read-aloud', 'home', 'Читать друг другу книгу вслух', 'Read a book aloud to each other', 'Бір-біріне дауыстап кітап оқу', 'По главе за вечер, по очереди, и обсуждать прочитанное за чаем.', 'One chapter per evening, taking turns, then talk it over with tea.', 'Кешіне бір тараудан кезекпен оқып, шай үстінде талқылаңдар.', 38),
  ('home-photo-album', 'home', 'Собрать бумажный альбом ваших фото', 'Make a paper album of your photos', 'Ортақ суреттерден қағаз альбом жасау', 'Распечатать лучшие снимки за год и подписать каждый от руки.', 'Print the best shots of the year and caption each one by hand.', 'Жылдың ең жақсы суреттерін басып шығарып, әрқайсысына қолмен бірер сөз жазыңдар.', 42),
  ('home-dream-trip-plan', 'home', 'Спланировать путешествие мечты', 'Plan your dream trip in detail', 'Арман сапарын жоспарлау', 'Маршрут, бюджет и список блюд, которые обязательно попробовать на месте.', 'Map the route, set a budget, and list the dishes to try once you''re there.', 'Бағытын, шығынын және сол жерде міндетті түрде татып көретін тағамдар тізімін жасаңдар.', 46),
  ('home-candlelight-dinner', 'home', 'Ужинать при свечах без телефонов', 'Dine by candlelight with no phones', 'Телефонсыз, шырақ жарығында кешкі ас ішу', 'Убрать телефоны в другую комнату и накрыть стол как в ресторане.', 'Leave the phones in another room and set the table like a restaurant.', 'Телефондарды басқа бөлмеге қойып, дастарқанды мейрамханадағыдай жайыңдар.', 50),
  ('home-karaoke-night', 'home', 'Устроить караоке-вечер дома', 'Host a karaoke night at home', 'Үйде караоке кешін өткізу', 'Песни выбирать друг для друга, а отказываться петь нельзя.', 'Pick songs for each other, and nobody is allowed to refuse.', 'Әндерді бір-біріңе таңдайсыңдар, ал бас тартуға болмайды.', 54),
  ('home-portraits', 'home', 'Нарисовать портреты друг друга', 'Draw portraits of each other', 'Бір-бірінің портретін салу', 'Десять минут на рисунок, без права стирать, а оба повесить на холодильник.', 'Ten minutes each, no erasing, then stick both on the fridge.', 'Әр суретке он минут, өшіруге болмайды, ал екеуін де тоңазытқышқа жапсырыңдар.', 58),
  ('home-month-review', 'home', 'Подводить итоги месяца за чаем', 'Review the month together over tea', 'Шай үстінде ай қорытындысын шығару', 'Три вопроса: что порадовало, что было трудно и чего хочется в следующем месяце.', 'Three questions: what made you happy, what was hard, what you want next month.', 'Үш сұрақ: не қуантты, не қиын болды және келесі айда не қалаймыз.', 62),
  ('home-windowsill-herbs', 'home', 'Посадить травы на подоконнике', 'Plant herbs on the windowsill', 'Терезе алдына дәмдеуіш шөп отырғызу', 'Базилик, мята и укроп в горшках, а первый урожай отправить в общий салат.', 'Basil, mint, and dill in pots, with the first harvest going into a salad.', 'Райхан, жалбыз бен аскөкті ыдыстарға отырғызып, алғашқы өнімді салатқа қосыңдар.', 66),
  ('home-childhood-dishes', 'home', 'Приготовить блюда из детства', 'Cook the dishes of your childhood', 'Балалық шақтағы тағамдарды пісіру', 'По одному блюду от каждого: то, что в семье готовили по выходным.', 'One dish from each of you: whatever your family made on weekends.', 'Әрқайсысы бала кезде үйде демалыс күндері пісірілетін бір тағамды дайындайды.', 70),
  ('home-dance-lesson', 'home', 'Выучить танец по видеоуроку', 'Learn a dance from a video lesson', 'Бейнесабақпен би үйрену', 'Вальс, сальса или бачата: по 20 минут каждый вечер, пока не выйдет связка.', 'Waltz, salsa, or bachata: 20 minutes a night until one routine clicks.', 'Вальс, сальса не бачата: бір қимыл тізбегі шыққанша күн сайын 20 минут жаттығыңдар.', 74),
  ('home-trilogy-marathon', 'home', 'Устроить марафон трилогии', 'Have a trilogy movie marathon', 'Трилогияны бір отырыста көру', 'Три фильма подряд, перерывы на еду и голосование за лучшую часть.', 'Three films in a row, food breaks, and a vote for the best one.', 'Арасында тамақтанып алып, соңында ең үздік бөлімге дауыс беріңдер.', 78),
  ('home-blind-tasting', 'home', 'Провести слепую дегустацию', 'Host a blindfolded tasting', 'Көзді байлап дәм тату', 'Чай, шоколад или соки: завязать друг другу глаза и угадывать вкус.', 'Tea, chocolate, or juices: blindfold each other and guess each flavor.', 'Шай, шоколад не шырын: көзді байлап алып, не екенін дәмінен табыңдар.', 82),
  ('home-36-questions', 'home', 'Ответить на 36 вопросов для сближения', 'Answer the 36 questions for closeness', 'Жақындастыратын 36 сұраққа жауап беру', 'Известный список психологов: по очереди, без спешки и честно.', 'The well-known psychology list: take turns and answer slowly and honestly.', 'Психологтардың белгілі тізімі: кезекпен, асықпай әрі шын жүректен жауап беріңдер.', 86),
  ('home-letter-to-future-child', 'home', 'Написать письмо будущему ребёнку', 'Write a letter to your future child', 'Болашақ балаға хат жазу', 'Рассказать, как вы познакомились и чего ждёте, и запечатать до встречи.', 'Tell how you met and what you hope for, and seal it until they can read it.', 'Қалай танысқандарыңды, неден үміттенетіндеріңді жазып, конвертке салып қойыңдар.', 90),
  ('home-time-capsule', 'home', 'Заложить капсулу времени на год', 'Make a one-year time capsule', 'Бір жылдық уақыт капсуласын жасау', 'Письма, фото и мелочи в коробку, а дату вскрытия отметить в календаре.', 'Letters, photos, and small things in a box, with the opening date marked.', 'Хаттар, суреттер мен ұсақ заттарды қорапқа салып, ашатын күнді белгілеп қойыңдар.', 94),
  ('home-pajama-day', 'home', 'Провести весь день в пижамах', 'Spend a whole day in pajamas', 'Күні бойы пижамамен жүру', 'Мультфильмы детства, еда из того, что есть в холодильнике, и никаких планов.', 'Childhood cartoons, food from whatever is in the fridge, and zero plans.', 'Балалық шақтың мультфильмдері, тоңазытқыштағы бар тамақ және ешқандай жоспар жоқ.', 98),
  ('home-mystery-ingredients', 'home', 'Приготовить ужин из пяти тайных продуктов', 'Cook with five mystery ingredients', 'Құпия бес өнімнен кешкі ас дайындау', 'Выбрать продукты друг другу втайне и дать себе на блюдо 40 минут.', 'Secretly pick the ingredients for each other and give yourselves 40 minutes.', 'Өнімдерді бір-біріңе жасырын таңдап, тағам дайындауға 40 минут беріңдер.', 102),
  ('home-decorate-cookies', 'home', 'Испечь и расписать печенье', 'Bake and decorate cookies', 'Печенье пісіріп, безендіру', 'Глазурь нескольких цветов и тема: нарисовать друг друга или общие шутки.', 'A few colors of icing and a theme: draw each other or your inside jokes.', 'Бірнеше түсті глазурьмен бір-біріңді не ортақ әзілдеріңді салыңдар.', 106),
  ('home-signature-lemonades', 'home', 'Придумать свои лимонады', 'Invent your own lemonades', 'Өзіндік лимонад ойлап табу', 'Фрукты, мята, газированная вода и придуманное название для каждого рецепта.', 'Fruit, mint, sparkling water, and a made-up name for every recipe.', 'Жеміс, жалбыз, газдалған су және әр рецептке ойдан шығарылған атау.', 110),
  ('home-coop-video-game', 'home', 'Пройти кооперативную игру вдвоём', 'Play through a co-op video game', 'Екі адамдық бейнеойынды бірге өту', 'Выбрать игру, которую не пройти в одиночку, и играть по уровню за вечер.', 'Pick a game built for two players and clear one level every evening.', 'Жалғыз өтуге болмайтын ойын таңдап, кешіне бір деңгейден ойнаңдар.', 114),
  ('home-candle-making', 'home', 'Отлить свечи своими руками', 'Make your own candles', 'Балауыздан шам құю', 'Воск, фитиль, баночки и любимый аромат, а первую свечу зажечь за ужином.', 'Wax, wicks, small jars, and a favorite scent, then light the first one at dinner.', 'Балауыз, білте, шағын ыдыс және сүйікті хош иіс, ал алғашқысын кешкі аста жағыңдар.', 118),
  ('home-reread-first-messages', 'home', 'Перечитать вашу первую переписку', 'Reread your very first messages', 'Алғашқы жазысқан хаттарды қайта оқу', 'Рассказать, о чем на самом деле думали тогда, и посмеяться над собой.', 'Tell each other what you were really thinking back then.', 'Сол кезде шынында не ойлағандарыңды бір-біріңе айтып, күліп алыңдар.', 122),
  ('home-story-playlist', 'home', 'Собрать плейлист вашей истории', 'Make a playlist of your story', 'Ортақ тарихтың плейлистін жасау', 'По песне на каждый важный момент, от знакомства до сегодняшнего дня.', 'One song for every key moment, from the day you met until today.', 'Танысқан күннен бүгінге дейінгі әр маңызды сәтке бір ән таңдаңдар.', 126),
  ('home-ice-cream', 'home', 'Сделать домашнее мороженое', 'Make homemade ice cream', 'Үйде балмұздақ жасау', 'Без мороженицы: сливки, сгущёнка, ягоды и вкус, придуманный вместе.', 'No machine needed: cream, condensed milk, berries, and a flavor you invent.', 'Арнайы құрылғысыз: кілегей, қойылтылған сүт, жидек және өздерің ойлап тапқан дәм.', 130),
  ('home-birdhouse', 'home', 'Смастерить скворечник или кормушку', 'Build a birdhouse or a bird feeder', 'Құстарға ұя не жемсалғыш жасау', 'Из досок или коробки из-под сока, а потом повесить и следить за гостями.', 'Use scrap wood or a juice carton, hang it up, and watch who visits.', 'Тақтайдан не шырын қорабынан жасап, іліп қойып, кімдер келетінін бақылаңдар.', 134),
  ('home-50-wishes', 'home', 'Составить список 50 общих желаний', 'Write a list of 50 shared wishes', 'Ортақ 50 тілектің тізімін жасау', 'Большие и маленькие, а список повесить на видное место и вычеркивать сбывшееся.', 'Big and small, hung where you''ll see it, crossing off each one that comes true.', 'Үлкен де, кішкентай да тілектерді жазып, тізімді көрінетін жерге іліңдер.', 138),
  ('home-short-film', 'home', 'Снять короткий фильм на телефон', 'Shoot a short film on your phone', 'Телефонға қысқа фильм түсіру', 'Сюжет на одну страницу, костюмы из шкафа и премьера в тот же вечер.', 'A one-page plot, costumes from the closet, and a premiere that same night.', 'Бір беттік сюжет, киім шкафынан костюм және сол кеште тұсаукесер.', 142),
  ('home-sushi-rolls', 'home', 'Скрутить роллы дома', 'Roll your own sushi at home', 'Үйде суши-ролл орау', 'Рис, нори и любые начинки, а самый кривой ролл съесть первым.', 'Rice, nori, any fillings you like, and eat the wonkiest roll first.', 'Күріш, нори, ішіне ұнағанның бәрі, ал ең қисық роллды бірінші жеңдер.', 146),
  ('home-morning-workout', 'home', 'Делать утреннюю зарядку вместе', 'Do a morning workout together', 'Таңертең бірге жаттығу жасау', 'Неделю подряд по 15 минут под одно видео, а наградой будет завтрак.', 'Fifteen minutes to the same video for a week, with breakfast as the reward.', 'Бір апта бойы бір бейнежазбамен 15 минуттан, ал сыйлығы таңғы ас.', 150),
  ('home-quiz-about-each-other', 'home', 'Сыграть в викторину друг о друге', 'Play a quiz about each other', 'Бір-бірі туралы викторина ойнау', 'По десять вопросов: любимое блюдо, первый страх, имя первого учителя.', 'Ten questions each: favorite dish, first fear, name of your first teacher.', 'Әрқайсысына он сұрақ: сүйікті тағамы, алғашқы қорқынышы, бірінші ұстазының аты.', 154),
  ('home-family-tree', 'home', 'Составить общее семейное древо', 'Draw your shared family tree', 'Екі әулеттің шежіресін жасау', 'Расспросить родных о прадедах и соединить две ветви на одном листе.', 'Ask relatives about great-grandparents and join both sides on one sheet.', 'Туыстардан жеті атаны сұрап, екі жақтың шежіресін бір параққа түсіріңдер.', 158),
  ('distance-same-recipe-call', 'distance', 'Приготовить ужин по одному рецепту', 'Cook the same recipe on a video call', 'Бір рецептпен кешкі ас дайындау', 'Купить одинаковые продукты, готовить на видеосвязи и сравнить, у кого вкуснее.', 'Buy the same ingredients, cook side by side on camera, and compare plates.', 'Бірдей өнім алып, бейнеқоңырауда қатар пісіріп, кімдікі дәмдірек екенін салыстырыңдар.', 1),
  ('distance-synced-movie', 'distance', 'Смотреть фильм синхронно', 'Watch a movie in sync', 'Фильмді бір мезетте қосып көру', 'Запустить на счёт три, выключить звук звонка и писать реакции в чат.', 'Press play on the count of three, mute the call, and react in the chat.', 'Үшке дейін санап қосып, қоңырау дыбысын өшіріп, әсерлеріңді чатқа жазыңдар.', 5),
  ('distance-walk-on-a-call', 'distance', 'Гулять в одно время на звонке', 'Walk at the same time while on a call', 'Қоңырауда тұрып бірге серуендеу', 'Описывать друг другу, что видно вокруг, и сфотографировать одну красивую деталь.', 'Describe what you see around you and each photograph one beautiful detail.', 'Айналада не көріп тұрғандарыңды айтып, бір әдемі бөлшекті суретке түсіріңдер.', 9),
  ('distance-paper-letters', 'distance', 'Писать друг другу бумажные письма', 'Send each other paper letters', 'Бір-біріне қағаз хат жазу', 'Отправить обычной почтой и молчать о содержании, пока письмо не дойдет.', 'Use regular mail and say nothing about what''s inside until it arrives.', 'Кәдімгі поштамен жіберіп, хат жеткенше ішінде не барын айтпаңдар.', 13),
  ('distance-open-when-letters', 'distance', 'Написать конверты на разные случаи', 'Write open-when letters', 'Түрлі сәтке арналған хаттар жазу', 'Когда грустно, не спится или скучаешь: подписать конверты и передать при встрече.', 'Open when sad, when you can''t sleep, when you miss me: hand them over in person.', 'Мұңайғанда, ұйқы келмегенде, сағынғанда ашатын хаттарды кездескенде беріңдер.', 17),
  ('distance-song-of-the-day', 'distance', 'Отправлять друг другу песню дня', 'Send each other a song of the day', 'Бір-біріне күннің әнін жіберу', 'Неделю подряд, с одной строкой о том, почему именно она сегодня.', 'For a week, each with one line on why this song, today.', 'Бір апта бойы, неге дәл осы ән екенін бір жолмен түсіндіріп отырыңдар.', 21),
  ('distance-same-book', 'distance', 'Читать одну книгу на расстоянии', 'Read the same book while apart', 'Алыста жүріп бір кітапты оқу', 'Договориться о главе на неделю и обсуждать её в воскресенье по видео.', 'Agree on a chapter a week and discuss it on Sunday over video.', 'Аптасына бір тарауға келісіп, жексенбі күні бейнеқоңырауда талқылаңдар.', 25),
  ('distance-bedtime-audiobook', 'distance', 'Слушать одну аудиокнигу перед сном', 'Listen to one audiobook before sleep', 'Ұйқы алдында бір аудиокітап тыңдау', 'Включить главу одновременно, а утром рассказать, на каком месте уснули.', 'Start a chapter at the same time and tell each other where you fell asleep.', 'Бір тарауды бір мезетте қосып, таңертең қай жерде ұйықтап кеткендеріңді айтыңдар.', 29),
  ('distance-surprise-delivery', 'distance', 'Заказать сюрприз с доставкой', 'Send a surprise food delivery', 'Жеткізу қызметімен тосынсый жіберу', 'Любимый десерт или горячий суп в тяжелый день, без предупреждения.', 'A favorite dessert or hot soup on a hard day, with no warning.', 'Ауыр күні ескертпестен сүйікті десерт не ыстық сорпа жіберу.', 33),
  ('distance-drawing-game', 'distance', 'Сыграть в онлайн-рисовалку', 'Play an online drawing guessing game', 'Онлайн сурет-жұмбақ ойнау', 'Рисовать и угадывать по очереди, а самые смешные рисунки сохранять.', 'Take turns drawing and guessing, and screenshot the funniest drawings.', 'Кезекпен сурет салып, жауабын табыңдар, ең күлкілі суреттерді сақтап қойыңдар.', 37),
  ('distance-photo-theme-week', 'distance', 'Провести неделю фото на одну тему', 'Run a week-long photo theme challenge', 'Апталық фото-сайыс өткізу', 'Каждый день новое слово, например красное, круглое или старое, и обмен снимками вечером.', 'A new word each day, like red, round, or old, and trade shots every evening.', 'Күн сайын жаңа сөз, мысалы қызыл, дөңгелек не ескі, ал кешке суреттермен алмасыңдар.', 41),
  ('distance-video-breakfast', 'distance', 'Завтракать вместе по видео', 'Have breakfast together over video', 'Бейнеқоңыраумен бірге таңғы ас ішу', 'Поставить телефон напротив тарелки и начать день с одной темы для разговора.', 'Prop the phone across from your plate and start the day with one topic.', 'Телефонды тарелканың қарсысына қойып, күнді бір әңгімемен бастаңдар.', 45),
  ('distance-same-constellation', 'distance', 'Искать одно созвездие одновременно', 'Find the same constellation at once', 'Бір шоқжұлдызды бір мезетте іздеу', 'Открыть звёздную карту в телефоне и найти его на небе из своих окон.', 'Open a star map app and spot it in the sky from your own windows.', 'Телефондағы жұлдыз картасын ашып, оны өз терезелеріңнен аспаннан табыңдар.', 49),
  ('distance-voice-diary', 'distance', 'Вести голосовой дневник друг для друга', 'Keep a voice diary for each other', 'Бір-біріне дауыстық күнделік жүргізу', 'Перед сном минута голосом: лучший и самый трудный момент дня.', 'One minute before bed: the best and the hardest moment of your day.', 'Ұйқы алдында бір минут: күннің ең жақсы және ең ауыр сәті.', 53),
  ('distance-care-package', 'distance', 'Собрать посылку с мелочами', 'Mail a care package of little things', 'Ұсақ-түйек салынған сәлемдеме жіберу', 'Любимый чай, записка, распечатанное фото и свитер, который пахнет вами.', 'Favorite tea, a note, a printed photo, and a sweater that smells like you.', 'Сүйікті шай, хат, басылған сурет және сенің иісің сіңген жемпір.', 57),
  ('distance-online-course', 'distance', 'Пройти один онлайн-курс вдвоём', 'Take the same online course', 'Бір онлайн курсты бірге оқу', 'Язык, рисунок или фото: уроки по расписанию и проверка заданий друг у друга.', 'A language, drawing, or photography: set lesson times and check each other''s work.', 'Тіл, сурет не фото: кестемен оқып, бір-біріңнің тапсырмаларыңды тексеріңдер.', 61),
  ('distance-macro-photo-riddle', 'distance', 'Загадывать предметы по фото вблизи', 'Guess objects from close-up photos', 'Жақыннан түсірілген заттарды табу', 'Снять вещь из дома очень крупно, а другой стороне угадать её с трёх попыток.', 'Shoot something at home extremely close up and give three tries to guess it.', 'Үйдегі затты өте жақыннан түсіріп, оны табуға үш мүмкіндік беріңдер.', 65),
  ('distance-plan-next-meeting', 'distance', 'Расписать следующую встречу по часам', 'Plan your next meeting hour by hour', 'Келесі кездесуді сағат бойынша жоспарлау', 'Вписать по одному сюрпризу от каждого и держать его в секрете до встречи.', 'Each of you slips in one surprise and keeps it secret until the day.', 'Әрқайсысы бір тосынсыйды жасырын қосып, оны кездескенше құпия ұстайды.', 69),
  ('distance-future-home-board', 'distance', 'Собрать доску идей для общего дома', 'Build a mood board for your future home', 'Болашақ үйдің идеялар тақтасын жинау', 'Кухня, свет, цвет стен: сохранять картинки в одну папку и обсуждать по выходным.', 'Kitchen, lighting, wall colors: save pictures to one folder and talk it over weekly.', 'Ас үй, жарық, қабырға түсі: суреттерді бір папкаға жинап, демалыста талқылаңдар.', 73),
  ('distance-window-sounds', 'distance', 'Обменяться звуками за окном', 'Swap the sounds outside your windows', 'Терезе сыртындағы дыбыстармен алмасу', 'Записать по минуте утреннего шума и угадывать каждый звук на чужой записи.', 'Record a minute of morning noise each and guess every sound in the other''s clip.', 'Таңғы шуды бір минут жазып алып, бір-біріңнің жазбаңдағы әр дыбысты табыңдар.', 77),
  ('distance-mini-lesson', 'distance', 'Провести друг другу мини-урок', 'Teach each other a mini lesson', 'Бір-біріне шағын сабақ өткізу', 'Пятнадцать минут о том, что умеете лучше всего: от фокусов до морских узлов.', 'Fifteen minutes on something you''re great at, from card tricks to sailor''s knots.', 'Әрқайсысы өзі ең жақсы білетін іс туралы он бес минут: карта фокусынан түйін түюге дейін.', 81),
  ('distance-online-escape-game', 'distance', 'Пройти онлайн-квест вдвоём', 'Solve an online escape game for two', 'Онлайн квестті бірге өту', 'У каждого своя половина подсказок, так что придётся много говорить.', 'Each of you sees half of the clues, so you''ll have to talk a lot.', 'Әрқайсысында кеңестің жартысы ғана, сондықтан көп сөйлесуге тура келеді.', 85),
  ('distance-long-distance-duet', 'distance', 'Записать песню дуэтом на расстоянии', 'Record a long-distance duet', 'Арақашықтықта дуэт ән жазу', 'Спеть свои партии под одну минусовку и свести две дорожки в простом приложении.', 'Sing your parts over one backing track and merge them in a simple app.', 'Бір фонограммамен өз бөліктеріңді айтып, екі жазбаны қарапайым қосымшада біріктіріңдер.', 89),
  ('distance-cook-by-instruction', 'distance', 'Готовить по инструкциям друг друга', 'Cook by each other''s video instructions', 'Бір-бірінің нұсқауымен тамақ пісіру', 'Шеф диктует рецепт коронного блюда по видео, но к плите не подходит.', 'The chef dictates their signature dish over video but never touches the stove.', 'Бас аспаз фирмалық тағамын бейнеқоңыраумен айтып тұрады, бірақ плитаға жоламайды.', 93),
  ('distance-wake-up-call', 'distance', 'Будить друг друга звонком', 'Wake each other up with a call', 'Бір-бірін қоңыраумен ояту', 'Неделю по очереди, и каждое утро с новым интересным фактом или песней.', 'Take turns for a week, with a new fun fact or song each morning.', 'Бір апта кезекпен оятып, әр таңда жаңа қызық дерек не ән айтыңдар.', 97),
  ('distance-video-scavenger-hunt', 'distance', 'Устроить поиск предметов по видео', 'Run a scavenger hunt over video', 'Бейнеқоңырауда зат іздеу ойынын ойнау', 'За минуту найти и показать в камеру что-то старше вас, что-то синее и что-то смешное.', 'One minute to show the camera something older than you, something blue, something silly.', 'Бір минутта өздеріңнен көне, көк түсті не күлкілі затты тауып көрсетіңдер.', 101),
  ('distance-album-listening', 'distance', 'Слушать один альбом от начала до конца', 'Listen to one album start to finish', 'Бір альбомды басынан аяғына дейін тыңдау', 'Одновременно, без перемотки, а после каждого трека ставить оценку.', 'At the same time, no skipping, and score every track afterwards.', 'Бір мезетте, өткізіп жібермей, әр әннен кейін баға беріңдер.', 105),
  ('distance-street-view-trip', 'distance', 'Гулять по улицам другой страны онлайн', 'Explore a foreign city on street view', 'Шетел көшелерін онлайн аралау', 'Вести друг друга по уличным панорамам по очереди и угадывать город по первой улице.', 'Take turns steering the street panoramas and guess the city from the first street.', 'Көше панорамасын кезекпен басқарып, қай қала екенін алғашқы көшеден табыңдар.', 109),
  ('distance-story-by-paragraph', 'distance', 'Писать историю по абзацу по очереди', 'Write a story one paragraph at a time', 'Кезекпен бір-бір абзацтан әңгіме жазу', 'Абзац в день, без обсуждения сюжета, а финал прочитать вслух при встрече.', 'A paragraph a day, no plot talk, and read the ending aloud when you meet.', 'Күніне бір абзац, сюжетті талқыламай, ал соңын кездескенде дауыстап оқыңдар.', 113),
  ('distance-childhood-photos', 'distance', 'Показать друг другу детские фото', 'Swap childhood photos and their stories', 'Балалық шақ суреттерімен бөлісу', 'По пять снимков от каждого, и к каждому история, которая ещё не звучала.', 'Five photos each, every one with a story that hasn''t been told yet.', 'Әрқайсысы бес суреттен, әр суреттің бұрын айтылмаған бір хикаясы болсын.', 117),
  ('distance-two-truths-and-a-lie', 'distance', 'Сыграть в две правды и одну ложь', 'Play two truths and a lie', 'Екі шындық, бір өтірік ойынын ойнау', 'Только факты, о которых вы ещё не говорили, и игра до пяти очков.', 'Only facts you''ve never mentioned before, first to five points wins.', 'Тек бұрын айтылмаған деректер, ал бес ұпайға бірінші жеткен жеңеді.', 121),
  ('distance-dressed-up-dinner', 'distance', 'Устроить ужин при параде по видео', 'Have a dressed-up dinner date on video', 'Бейнеқоңыраумен сәнді кешкі ас ішу', 'Нарядиться как в ресторан, зажечь свечу и не говорить о работе.', 'Dress up as if for a restaurant, light a candle, and skip all work talk.', 'Мейрамханаға барғандай киініп, шырақ жағып, жұмыс туралы сөйлеспеңдер.', 125),
  ('distance-same-seeds', 'distance', 'Посадить одинаковые семена', 'Plant the same seeds in both homes', 'Екі үйде бірдей тұқым егу', 'Растить по горшку у себя и раз в неделю обмениваться фото ростков.', 'Grow a pot each and swap sprout photos once a week.', 'Әрқайсысы өз ыдысын күтіп, өскіннің суретін аптасына бір рет жібереді.', 129),
  ('distance-gratitude-note', 'distance', 'Писать по три благодарности за день', 'Write three gratitudes every evening', 'Күн сайын ризашылық жазбасын жүргізу', 'Каждый вечер в общую заметку, а в конце месяца перечитать вместе.', 'Add them to one shared note each night and reread it together at month''s end.', 'Әр кеш ортақ жазбаға үш нәрсе қосып, ай соңында бірге қайта оқыңдар.', 133),
  ('distance-sandbox-house', 'distance', 'Построить общий дом в игре-песочнице', 'Build a shared house in a sandbox game', 'Ойын әлемінде ортақ үй салу', 'Поделить сад и интерьер между собой и заходить туда по вечерам.', 'Split the garden and the interior between you and visit it in the evenings.', 'Бақ пен ішкі безендіруді бөлісіп, кешкісін сол үйге кіріп тұрыңдар.', 137),
  ('distance-slow-chess', 'distance', 'Играть в шахматы по ходу в день', 'Play chess one move a day', 'Күніне бір жүрістен шахмат ойнау', 'Медленная партия по переписке, и к каждому ходу короткое сообщение.', 'A slow correspondence game, with a short message sent along with each move.', 'Хат арқылы баяу ойын, әр жүріске қысқа хабарлама қосып жіберіңдер.', 141),
  ('distance-hidden-notes', 'distance', 'Спрятать записки перед разлукой', 'Hide notes before saying goodbye', 'Қоштасар алдында хаттар тығып кету', 'Разложить их по карманам и книгам, чтобы находилось по одной в неделю.', 'Tuck them into pockets and books so one turns up every week.', 'Қалталар мен кітаптарға салып кетіңдер, аптасына біреуі табылып тұратындай.', 145),
  ('distance-step-challenge', 'distance', 'Устроить соревнование по шагам', 'Hold a step-count challenge', 'Қадам санауда жарысу', 'Цель на неделю, ежедневный отчет скриншотом и приз за победу при встрече.', 'A weekly goal, a daily screenshot check-in, and a prize at your next meeting.', 'Бір апталық мақсат, күн сайын скриншотпен есеп және кездескенде жүлде.', 149),
  ('distance-poems', 'distance', 'Написать друг другу стихи', 'Write each other a poem', 'Бір-біріне өлең жазу', 'Хотя бы четыре строки, рифма не обязательна, а читать вслух на звонке.', 'At least four lines, rhyme optional, read aloud on a call.', 'Кемінде төрт жол, ұйқас міндетті емес, қоңырауда дауыстап оқыңдар.', 153),
  ('distance-our-podcast', 'distance', 'Записать подкаст о вашей истории', 'Record a podcast about your story', 'Ортақ тарих туралы подкаст жазу', 'Задать друг другу три вопроса о знакомстве и сохранить запись на память.', 'Ask each other three questions about how you met and keep the recording.', 'Танысуларың туралы бір-біріңе үш сұрақ қойып, жазбаны естелікке сақтаңдар.', 157),
  ('city-market-dinner', 'city', 'Собрать ужин на рынке', 'Shop a market for tonight''s dinner', 'Базардан кешкі асқа өнім таңдау', 'Небольшой бюджет и правило: брать только то, что вы ни разу не готовили.', 'A small budget and one rule: buy only things you''ve never cooked before.', 'Шағын бюджет және бір шарт: бұрын ешқашан пісірмеген өнімдерді ғана алу.', 3),
  ('city-park-picnic', 'city', 'Устроить пикник в парке', 'Have a picnic in the park', 'Саябақта пикник жасау', 'Термос, плед, бутерброды и бадминтон или карты на после обеда.', 'A thermos, a blanket, sandwiches, and badminton or cards for afterwards.', 'Термос, жамылғы, бутерброд және түстен кейінге бадминтон не карта алыңдар.', 7),
  ('city-new-museum', 'city', 'Сходить в музей, где вы ещё не были', 'Visit a museum you''ve never been to', 'Бұрын бармаған мұражайға бару', 'Выбрать по экспонату и провести друг другу мини-экскурсию у него.', 'Each of you picks one exhibit and gives the other a mini tour of it.', 'Әрқайсысы бір жәдігер таңдап, екіншісіне шағын экскурсия жүргізеді.', 11),
  ('city-sunrise-high-point', 'city', 'Встретить рассвет на высокой точке', 'Watch the sunrise from a high spot', 'Таңды биік жерде қарсы алу', 'Холм, мост или открытая крыша, термос с чаем и выход ещё затемно.', 'A hill, a bridge, or an open rooftop, plus a thermos and a pre-dawn start.', 'Төбе, көпір не ашық шатыр, термос шай және қараңғыда шығу.', 15),
  ('city-new-cuisine-cafe', 'city', 'Поужинать в кафе незнакомой кухни', 'Eat at a cafe with a cuisine new to you', 'Бейтаныс ұлттық тағамдар кафесіне бару', 'Заказать блюдо, название которого трудно выговорить, и узнать, как его едят.', 'Order the dish with the hardest name to pronounce and ask how to eat it.', 'Атауын айту қиын тағамға тапсырыс беріп, оны қалай жейтінін сұраңдар.', 19),
  ('city-pottery-class', 'city', 'Сходить на мастер-класс по гончарству', 'Take a pottery class', 'Қыш жасау шеберлік сабағына бару', 'Слепить кружки друг для друга и пить из них дома.', 'Make mugs for each other and drink from them at home.', 'Бір-біріңе кесе жасап, кейін үйде соларымен шай ішіңдер.', 23),
  ('city-shelter-dogs', 'city', 'Погулять с собаками из приюта', 'Walk dogs from an animal shelter', 'Баспанадағы иттерді серуендету', 'Узнать, когда приют ждёт волонтёров, и принести корм или старые пледы.', 'Find out when the shelter takes volunteers and bring food or old blankets.', 'Баспана еріктілерді қашан күтетінін біліп, жем не ескі көрпе апарыңдар.', 27),
  ('city-tourists-at-home', 'city', 'Стать туристами в своём городе', 'Be tourists in your own city', 'Өз қалаларыңда турист болу', 'Пройти маршрут из путеводителя, будто приехали только вчера.', 'Follow a guidebook route as if you only arrived yesterday.', 'Кеше ғана келгендей, жолнұсқадағы бағытпен жүріп шығыңдар.', 31),
  ('city-outdoor-skating', 'city', 'Покататься на коньках под открытым небом', 'Go ice skating at an outdoor rink', 'Ашық мұз айдынында коньки тебу', 'Первый круг держась за руки, а потом какао из термоса.', 'Hold hands for the first lap, then warm up with cocoa from a thermos.', 'Алғашқы айналымды қол ұстасып жүріп, сосын термостағы какаомен жылыныңдар.', 35),
  ('city-bike-ride', 'city', 'Прокатиться на велосипедах по городу', 'Ride bikes across the city', 'Велосипедпен қаланы аралау', 'Взять два велосипеда напрокат и проехать по паркам, где обычно ходите пешком.', 'Rent two bikes and ride through the parks you usually cross on foot.', 'Жалға екі велосипед алып, әдетте жаяу жүретін саябақтарды аралаңдар.', 39),
  ('city-night-walk', 'city', 'Гулять по ночному городу с термосом', 'Take a night walk with a thermos', 'Түнгі қалада термоспен серуендеу', 'Выйти после одиннадцати и пройти улицами, которые днем стоят в пробках.', 'Head out after eleven and stroll the streets that are jammed all day.', 'Сағат он бірден кейін шығып, күндіз кептеліс болатын көшелермен жүріңдер.', 43),
  ('city-bookshop-swap', 'city', 'Выбрать друг другу книгу в магазине', 'Pick a book for each other at a bookshop', 'Кітап дүкенінде бір-біріне кітап таңдау', 'Пятнадцать минут на тайный выбор, а на первой странице написать пожелание.', 'Fifteen minutes to choose in secret, then write a note on the first page.', 'Он бес минут құпия таңдап, бірінші бетіне тілек жазып сыйлаңдар.', 47),
  ('city-random-play', 'city', 'Сходить на спектакль наугад', 'See a play picked at random', 'Кездейсоқ таңдалған спектакльге бару', 'Выбрать постановку по афише не глядя и обсудить её по дороге домой.', 'Choose a show from the listings without looking and discuss it on the way home.', 'Афишадан қойылымды көзді жұмып таңдап, үйге қайтар жолда талқылаңдар.', 51),
  ('city-live-concert', 'city', 'Сходить на живой концерт', 'Go to a live concert', 'Жанды музыка концертіне бару', 'Филармония, джаз или местная группа: жанр, который никто из вас обычно не слушает.', 'Orchestra, jazz, or a local band: a genre neither of you usually listens to.', 'Филармония, джаз не жергілікті топ: екеуің де әдетте тыңдамайтын жанр.', 55),
  ('city-planetarium', 'city', 'Сходить в планетарий', 'Visit a planetarium', 'Планетарийге бару', 'Сесть в центре зала, а после сеанса задать лектору самый странный вопрос.', 'Sit in the middle of the dome and ask the presenter your strangest question after.', 'Залдың ортасына отырып, сеанстан кейін дәріскерге ең оғаш сұрақ қойыңдар.', 59),
  ('city-botanical-garden', 'city', 'Погулять по ботаническому саду', 'Stroll through a botanical garden', 'Ботаникалық бақта серуендеу', 'Найти самое старое дерево и самый странный цветок и сфотографироваться у них.', 'Find the oldest tree and the strangest flower and take a photo by each.', 'Ең көне ағаш пен ең ерекше гүлді тауып, жанында суретке түсіңдер.', 63),
  ('city-bowling-for-a-wish', 'city', 'Сыграть в боулинг на желание', 'Bowl for a wish', 'Тілекке боулинг ойнау', 'Три партии, а за победу - одно небольшое желание в тот же вечер.', 'Three games, and the winner gets one small wish granted that evening.', 'Үш ойын, ал жеңімпаздың бір шағын тілегі сол кеште орындалады.', 67),
  ('city-climbing-gym', 'city', 'Попробовать скалодром', 'Try an indoor climbing gym', 'Скалодромда өрмелеп көру', 'Взять вводное занятие с инструктором и научиться страховать друг друга.', 'Book an intro session with an instructor and learn to belay each other.', 'Нұсқаушымен кіріспе сабаққа жазылып, бір-біріңді сақтандыруды үйреніңдер.', 71),
  ('city-trivia-night', 'city', 'Сыграть в квиз командой из двоих', 'Join a trivia night as a team of two', 'Екеулік командамен квиз ойнау', 'Найти ближайшую игру в кафе и придумать смешное название команды.', 'Find a trivia game at a cafe and come up with a funny team name.', 'Кафедегі жақын ойынды тауып, командаға күлкілі ат ойлап табыңдар.', 75),
  ('city-flea-market', 'city', 'Найти сокровище на барахолке', 'Hunt for treasure at a flea market', 'Ескі заттар базарынан қазына іздеу', 'Небольшая сумма на каждого и задача найти друг другу самый странный подарок.', 'A small budget each and a mission to find the strangest gift for each other.', 'Әрқайсысына шағын сома, ал міндет: бір-біріңе ең оғаш сыйлықты табу.', 79),
  ('city-bus-to-the-end', 'city', 'Проехать автобусный маршрут до конца', 'Ride a bus line to the very end', 'Автобуспен соңғы аялдамаға дейін бару', 'Выбрать незнакомый номер, выйти на конечной и найти там место для чая.', 'Pick an unfamiliar route, get off at the last stop, and find a spot for tea.', 'Бейтаныс бағытты таңдап, соңғы аялдамада түсіп, сол жерден шай ішетін орын табыңдар.', 83),
  ('city-opening-breakfast', 'city', 'Позавтракать в кафе к самому открытию', 'Have breakfast at a cafe right at opening', 'Кафе ашылған бетте таңғы ас ішу', 'Прийти первыми гостями и смотреть, как за окном просыпается улица.', 'Be the first guests and watch the street wake up outside the window.', 'Алғашқы қонақ болып кіріп, терезеден көшенің оянғанын тамашалаңдар.', 87),
  ('city-street-food-crawl', 'city', 'Устроить тур по уличной еде', 'Go on a street food crawl', 'Көше тағамдарын татып шығу', 'Пять разных точек, одна порция на двоих в каждой и оценки по десятибалльной шкале.', 'Five different stalls, one shared portion at each, and scores out of ten.', 'Бес түрлі орын, әр жерде екеуге бір порция және он балдық баға.', 91),
  ('city-contemporary-art', 'city', 'Посетить выставку современного искусства', 'See a contemporary art exhibition', 'Заманауи өнер көрмесіне бару', 'Сначала придумать свою трактовку работы и только потом прочитать подпись.', 'Make up your own meaning for a piece before reading its label.', 'Алдымен туындының мағынасын өздерің ойлап, сосын ғана сипаттамасын оқыңдар.', 95),
  ('city-open-air-cinema', 'city', 'Сходить в кино под открытым небом', 'Catch an open-air movie screening', 'Ашық аспан астындағы киноға бару', 'Летом поискать показы в парках, взять плед и домашний попкорн.', 'Look for summer screenings in parks and bring a blanket and homemade popcorn.', 'Жазда саябақтағы көрсетілімдерді іздеп, жамылғы мен үйде жасалған попкорн алыңдар.', 99),
  ('city-sledding', 'city', 'Кататься с горки на ватрушках', 'Go sledding down a snowy hill', 'Қарлы төбеден шана тебу', 'Найти самую длинную горку в городе, а потом греться чаем с баурсаками.', 'Find the longest slope in town, then warm up with tea and baursaks.', 'Қаладағы ең ұзын төбені тауып, сосын бауырсақ пен шаймен жылыныңдар.', 103),
  ('city-rowboat', 'city', 'Покататься на лодке в парке', 'Take a rowboat out in the park', 'Саябақ көлінде қайықпен жүзу', 'Грести по очереди и остановиться посреди пруда ради фото.', 'Take turns rowing and stop in the middle of the pond for a photo.', 'Кезекпен ескек есіп, тоғанның ортасында суретке түсуге тоқтаңдар.', 107),
  ('city-ferris-wheel', 'city', 'Прокатиться на колесе обозрения', 'Ride the Ferris wheel', 'Шолу дөңгелегіне міну', 'Сесть перед закатом и найти сверху места, где вы уже бывали вместе.', 'Go just before sunset and spot places you''ve already been together.', 'Күн батар алдында мініп, жоғарыдан бірге болған жерлеріңді іздеңдер.', 111),
  ('city-library-day', 'city', 'Провести день в читальном зале', 'Spend a day in a library reading room', 'Кітапхананың оқу залында күн өткізу', 'Набрать книг на одну тему и шёпотом делиться самыми интересными фактами.', 'Grab a stack of books on one topic and whisper the best facts to each other.', 'Бір тақырыпқа бір бума кітап алып, ең қызық деректерді сыбырлап айтыңдар.', 115),
  ('city-coin-flip-walk', 'city', 'Гулять по незнакомому району без карты', 'Explore a new neighborhood without a map', 'Бейтаныс ауданды картасыз аралау', 'На каждом перекрёстке бросать монетку: орёл направо, решка налево.', 'Flip a coin at every crossing: heads go right, tails go left.', 'Әр қиылыста тиын лақтырыңдар: елтаңба шықса оңға, сан шықса солға.', 119),
  ('city-public-lecture', 'city', 'Сходить на открытую лекцию', 'Attend a free public lecture', 'Ашық дәріске бару', 'Тема, далекая от работы обоих, а по дороге домой пересказать главное друг другу.', 'Pick a topic far from both your jobs and retell the key points on the way home.', 'Екеуіңнің де жұмыстарыңнан алыс тақырып таңдап, қайтар жолда негізгісін бір-біріңе айтыңдар.', 123),
  ('city-trampoline-park', 'city', 'Попрыгать в батутном парке', 'Bounce at a trampoline park', 'Батут саябағында секіру', 'Час прыжков, конкурс на самый смешной прыжок и видео в замедленной съемке.', 'An hour of jumping, a contest for the silliest jump, and slow-motion videos.', 'Бір сағат секіріс, ең күлкілі секіріске жарыс және баяу түсірілген бейне.', 127),
  ('city-swimming-pool', 'city', 'Сходить в бассейн вместе', 'Go swimming at a pool', 'Бассейнге бірге бару', 'Научить друг друга одному стилю плавания или посоревноваться на одной дорожке.', 'Teach each other a stroke, or just race one length.', 'Бір-біріңе жүзу әдісін үйретіңдер не бір жолақта жарысыңдар.', 131),
  ('city-tree-planting', 'city', 'Посадить деревья на субботнике', 'Plant trees at a community event', 'Сенбілікте ағаш отырғызу', 'Найти городскую акцию по озеленению и запомнить, где растет ваше дерево.', 'Join a city greening day and remember exactly where your tree grows.', 'Қаланы көгалдандыру шарасына қосылып, ағаштарыңның қай жерде өсетінін есте сақтаңдар.', 135),
  ('city-cheer-local-team', 'city', 'Поболеть за местную команду', 'Cheer for a local team at a match', 'Стадионда жергілікті команданы қолдау', 'Нарисовать плакат, выучить одну кричалку и надеть цвета клуба.', 'Make a poster, learn one chant, and wear the team colors.', 'Плакат жасап, бір ұран жаттап, команданың түсіндегі киім киіңдер.', 139),
  ('city-fly-a-kite', 'city', 'Запустить воздушного змея', 'Fly a kite', 'Батпырауық ұшыру', 'Собрать змея из реек и пакета или купить простого и дождаться ветреного дня.', 'Build one from sticks and a plastic bag or buy a simple one, then wait for a windy day.', 'Таяқша мен пакеттен өздерің жасаңдар не қарапайымын алыңдар, ал күнді желді таңдаңдар.', 143),
  ('city-zoo', 'city', 'Сходить в зоопарк', 'Visit the zoo', 'Хайуанаттар бағына бару', 'Найти зверя, похожего на каждого из вас, и узнать о нем три факта.', 'Find an animal that resembles each of you and learn three facts about it.', 'Екеуіңе ұқсайтын жануарларды тауып, әрқайсысы туралы үш дерек біліңдер.', 147),
  ('city-first-date-place', 'city', 'Вернуться на место первого свидания', 'Return to your first date spot', 'Алғаш кездескен жерге қайта бару', 'Повторить тот же маршрут и заказать то же самое, если место ещё работает.', 'Retrace the route and order exactly the same thing, if the place is still open.', 'Сол бағытты қайталап, орын әлі жұмыс істесе, дәл сол тағамға тапсырыс беріңдер.', 151),
  ('city-cooking-class', 'city', 'Сходить на кулинарный мастер-класс', 'Take a cooking class together', 'Аспаздық шеберлік сабағына бару', 'Выбрать блюдо, на которое дома не решались, например лагман с тянутой лапшой.', 'Pick a dish you''d never dare at home, like lagman with hand-pulled noodles.', 'Үйде жасауға батылдарың бармаған тағамды таңдаңдар, мысалы созба лағман.', 155),
  ('city-standup-show', 'city', 'Сходить на стендап или импровизацию', 'See a stand-up or improv show', 'Стендап не импровизация шоуына бару', 'Сесть подальше от сцены, если не хочется стать частью шоу.', 'Sit away from the stage unless you want to become part of the act.', 'Шоуға қатысқыларың келмесе, сахнадан алысырақ отырыңдар.', 159),
  ('trip-mountain-day-hike', 'trip', 'Сходить в однодневный поход в горы', 'Go on a day hike in the mountains', 'Тауға бір күндік жорыққа шығу', 'Выйти рано, взять бутерброды и горячий чай, а маршрут выбрать по силам обоим.', 'Start early, pack sandwiches and hot tea, and pick a trail you can both manage.', 'Ерте шығып, бутерброд пен ыстық шай алып, екеуіңе де ауыр емес бағыт таңдаңдар.', 4),
  ('trip-mountain-lake', 'trip', 'Доехать до горного озера', 'Reach a mountain lake', 'Тау көліне дейін бару', 'Устроить привал у воды и сделать фото, которое повторить ровно через год.', 'Rest by the water and take a photo you''ll recreate exactly one year later.', 'Су жағасында демалып, дәл бір жылдан кейін қайталайтын сурет түсіріңдер.', 8),
  ('trip-steppe-meteor-shower', 'trip', 'Поехать в степь смотреть звездопад', 'Watch a meteor shower in the steppe', 'Далаға аққан жұлдыз көруге бару', 'В середине августа отъехать подальше от огней и считать падающие звёзды.', 'In mid-August, drive far from the lights and count the shooting stars.', 'Тамыздың ортасында жарықтан алыс кетіп, аққан жұлдыздарды санаңдар.', 12),
  ('trip-no-plan-road-trip', 'trip', 'Отправиться в поездку без плана', 'Take a road trip with no plan', 'Жоспарсыз жолға шығу', 'Сворачивать к каждому указателю, который покажется интересным, и вернуться к ночи.', 'Turn off at every sign that looks interesting and be home by night.', 'Қызық көрінген әр көрсеткішке бұрылып, түнге қарай үйге оралыңдар.', 16),
  ('trip-overnight-train', 'trip', 'Поехать в другой город ночным поездом', 'Take an overnight train to another city', 'Түнгі пойызбен басқа қалаға бару', 'Чай в подстаканниках, настольная игра в дорогу и рассвет за окном.', 'Tea in glass holders, a travel board game, and sunrise outside the window.', 'Купедегі шай, жолға арналған үстел ойыны және терезе сыртындағы таң.', 20),
  ('trip-tent-camping', 'trip', 'Переночевать в палатке на природе', 'Spend a night camping in a tent', 'Табиғатта шатыр тігіп түнеу', 'Выбрать проверенную стоянку, взять фонарики и готовить ужин на горелке.', 'Choose a known campsite, bring headlamps, and cook dinner on a camp stove.', 'Белгілі тұрақты таңдап, қалта шам алып, кешкі асты газ оттықта пісіріңдер.', 24),
  ('trip-sanatorium-weekend', 'trip', 'Провести выходные в санатории', 'Spend a weekend at a health resort', 'Демалыс күндерін шипажайда өткізу', 'Прогулки, процедуры, сон до обеда и минеральная вода из источника.', 'Walks, treatments, sleeping in, and mineral water straight from the spring.', 'Серуен, ем-шара, түске дейін ұйқы және бұлақтан минералды су.', 28),
  ('trip-canyon', 'trip', 'Спуститься на дно каньона', 'Hike down into a canyon', 'Каньон түбіне түсу', 'Проверить маршрут заранее, выехать на рассвете и взять много воды.', 'Check the route ahead of time, leave at dawn, and carry plenty of water.', 'Бағытты алдын ала тексеріп, таң сәріде шығып, суды мол алыңдар.', 32),
  ('trip-horse-ride', 'trip', 'Покататься верхом за городом', 'Go horseback riding outside the city', 'Қала сыртында атпен серуендеу', 'Записаться на прогулку с инструктором по степи или предгорьям для новичков.', 'Book a guided beginner ride through the steppe or the foothills.', 'Нұсқаушымен бірге жаңадан бастаушыларға арналған серуенге жазылыңдар: далада не тау бөктерінде.', 36),
  ('trip-village-stay', 'trip', 'Пожить пару дней в ауле', 'Stay a couple of days in a village', 'Ауылда бірер күн тұру', 'Найти гостевой дом, помочь хозяевам по хозяйству и записать местные рецепты.', 'Find a guesthouse, help the hosts with chores, and write down local recipes.', 'Қонақ үй тауып, үй иелеріне шаруада көмектесіп, жергілікті рецепттерді жазып алыңдар.', 40),
  ('trip-yurt-night', 'trip', 'Переночевать в юрте', 'Spend a night in a yurt', 'Киіз үйде түнеу', 'Расспросить хозяев, как устроена юрта, и проснуться под звуки степи.', 'Ask the hosts how the yurt is built and wake up to the sounds of the steppe.', 'Иелерінен киіз үйдің қалай құрылатынын сұрап, таңды дала дыбысымен қарсы алыңдар.', 44),
  ('trip-fishing', 'trip', 'Съездить на рыбалку', 'Go fishing for a day', 'Балық аулауға бару', 'Одолжить удочки у друзей, а улов, даже самый маленький, пожарить на месте.', 'Borrow rods from friends and fry the catch on the spot, however small.', 'Қармақты достардан сұрап алып, ауланған балықты кішкентай болса да сол жерде қуырыңдар.', 48),
  ('trip-apple-picking', 'trip', 'Собрать яблоки в саду', 'Pick apples at an orchard', 'Бақтан алма теру', 'Осенью найти сад, где можно собирать самим, и потом испечь шарлотку.', 'Find a pick-your-own orchard in autumn and bake an apple pie afterwards.', 'Күзде өздерің теруге болатын бақ тауып, кейін алма бәлішін пісіріңдер.', 52),
  ('trip-waterfall-hike', 'trip', 'Дойти до водопада', 'Hike to a waterfall', 'Сарқырамаға дейін жаяу бару', 'Выбрать тропу, где можно идти не спеша, и пообедать на камнях у воды.', 'Pick an easy-paced trail and have lunch on the rocks by the water.', 'Асықпай жүруге болатын соқпақ таңдап, су жанындағы тастарда түскі ас ішіңдер.', 56),
  ('trip-lake-summer-day', 'trip', 'Провести летний день на озере', 'Spend a summer day at a lake', 'Жазда көл жағасында күн өткізу', 'Купаться, читать вслух в тени и уехать только после заката.', 'Swim, read aloud in the shade, and only leave after sunset.', 'Шомылып, көлеңкеде кітап оқып, күн батқаннан кейін ғана қайтыңдар.', 60),
  ('trip-small-town', 'trip', 'Съездить в соседний маленький город', 'Explore a nearby small town', 'Көршілес шағын қаланы аралау', 'Начать с краеведческого музея и спросить местных, где самая вкусная выпечка.', 'Start at the local history museum and ask locals where the best bakery is.', 'Өлкетану мұражайынан бастап, жергіліктілерден ең дәмді тоқаш қайда екенін сұраңдар.', 64),
  ('trip-cave-with-guide', 'trip', 'Исследовать пещеру с гидом', 'Explore a cave with a guide', 'Жол бастаушымен үңгір аралау', 'Только с опытным проводником, в удобной обуви и с налобными фонариками.', 'Only with an experienced guide, sturdy shoes, and headlamps.', 'Тек тәжірибелі жол бастаушымен, ыңғайлы аяқ киіммен және маңдай шаммен.', 68),
  ('trip-sand-dunes', 'trip', 'Увидеть песчаные барханы', 'See the sand dunes', 'Құм шағылдарын көруге бару', 'Подняться на гребень к закату и съехать вниз на куске картона.', 'Climb a ridge at sunset and slide back down on a piece of cardboard.', 'Күн батарда шағылдың жотасына шығып, картон бетімен төмен сырғанаңдар.', 72),
  ('trip-birdwatching', 'trip', 'Понаблюдать за птицами на озере', 'Go birdwatching at a lake', 'Көл жағасында құстарды бақылау', 'Взять бинокль, определитель в телефоне и записывать каждый новый вид.', 'Bring binoculars and a bird ID app, and log every new species you spot.', 'Дүрбі мен телефондағы анықтағышты алып, әр жаңа түрді жазып отырыңдар.', 76),
  ('trip-ski-day', 'trip', 'Покататься на лыжах или сноуборде', 'Go skiing or snowboarding for a day', 'Шаңғы не сноуборд тебу', 'Взять снаряжение напрокат и первый час заниматься с инструктором.', 'Rent the gear and spend the first hour with an instructor.', 'Жабдықты жалға алып, алғашқы сағатты нұсқаушымен өткізіңдер.', 80),
  ('trip-wild-tulips', 'trip', 'Найти дикие тюльпаны в степи', 'Find wild tulips in the steppe', 'Даладан жабайы қызғалдақ іздеу', 'Весной поехать любоваться и фотографировать, но цветы не рвать.', 'Go in spring to admire and photograph them, but never pick them.', 'Көктемде тамашалап, суретке түсіріңдер, бірақ гүлдерді жұлмаңдар.', 84),
  ('trip-kazan-plov', 'trip', 'Сварить плов в казане на природе', 'Cook plov in a kazan outdoors', 'Табиғат аясында қазанда палау басу', 'Найти место, где можно разводить костёр, поделить роли и не поднимать крышку рано.', 'Pick a spot where fires are allowed, split the jobs, and don''t lift the lid early.', 'От жағуға рұқсат етілген жер таңдап, міндетті бөлісіп, қақпағын ерте ашпаңдар.', 88),
  ('trip-calm-river-kayak', 'trip', 'Сплавиться на байдарке по спокойной реке', 'Paddle a kayak down a calm river', 'Тыныш өзенмен байдаркада жүзу', 'Только с инструктором и в спасжилетах, а на полпути перекусить на берегу.', 'Only with a guide and life vests, with a snack stop on the bank halfway.', 'Тек нұсқаушымен және құтқару кеудешесімен, жолдың ортасында жағада тамақтаныңдар.', 92),
  ('trip-petroglyphs', 'trip', 'Найти древние петроглифы', 'Seek out ancient petroglyphs', 'Ежелгі жартас суреттерін іздеу', 'Почитать о них заранее и угадывать, что хотели сказать древние художники.', 'Read up beforehand and guess what the ancient artists were trying to say.', 'Алдын ала оқып алып, көне суретшілер не айтқысы келгенін болжаңдар.', 96),
  ('trip-silk-road-town', 'trip', 'Посетить древний город Шёлкового пути', 'Visit an ancient Silk Road town', 'Ұлы Жібек жолындағы көне қалаға бару', 'Взять местного гида и узнать, какие товары здесь везли караваны.', 'Hire a local guide and learn what goods the caravans carried through.', 'Жергілікті гид алып, керуендер мұнда қандай тауар тасығанын біліңдер.', 100),
  ('trip-forest-foraging', 'trip', 'Собирать ягоды или грибы в лесу', 'Forage berries or mushrooms in a forest', 'Орманда жидек не саңырауқұлақ теру', 'Брать только то, что точно знаете, а из добычи сварить варенье или суп.', 'Pick only what you know for sure, then make jam or soup from your haul.', 'Тек нақты білетін түрлерді теріп, олжадан тосап не сорпа пісіріңдер.', 104),
  ('trip-nature-reserve', 'trip', 'Съездить в заповедник с экскурсией', 'Visit a nature reserve with a ranger', 'Қорыққа экскурсиямен бару', 'Узнать правила посещения заранее и попросить рейнджера показать следы животных.', 'Check the visiting rules first and ask the ranger to show you animal tracks.', 'Келу ережесін алдын ала біліп, қорықшыдан жануар іздерін көрсетуін сұраңдар.', 108),
  ('trip-eagle-hunters', 'trip', 'Увидеть охоту с беркутом', 'See a golden eagle hunter at work', 'Бүркітші өнерін тамашалау', 'Найти праздник или хозяйство, где показывают ловчих птиц, и поговорить с беркутчи.', 'Find a festival or farm that shows hunting birds and talk to the handler.', 'Құсбегілік өнер көрсетілетін мереке не шаруашылық тауып, бүркітшімен сөйлесіңдер.', 112),
  ('trip-offline-weekend', 'trip', 'Провести выходные без связи на природе', 'Spend an offline weekend in nature', 'Табиғатта байланыссыз демалыс өткізу', 'Оставить один телефон для экстренных случаев, а остальное время - только вы и тишина.', 'Keep one phone for emergencies, and the rest is just you two and the quiet.', 'Төтенше жағдайға бір телефон қалдырып, қалған уақытта тек екеуің және тыныштық.', 116),
  ('trip-snowy-forest', 'trip', 'Пройти по заснеженному лесу', 'Walk through a snowy forest', 'Қарлы орманда серуендеу', 'Тропа по свежему снегу, облепиховый чай в термосе и снеговик на привале.', 'A trail through fresh snow, sea buckthorn tea in a thermos, and a snowman at the rest stop.', 'Жаңа жауған қардағы соқпақ, термостағы шырғанақ шайы және аялдамада аққала.', 120),
  ('trip-geocaching', 'trip', 'Найти тайник по GPS-координатам', 'Go geocaching outside the city', 'Координатпен жасырылған қорапты іздеу', 'Выбрать в приложении для геокэшинга тайник за городом и оставить в нем свою записку.', 'Find a nearby cache in a geocaching app and leave your own note inside.', 'Геокэшинг қосымшасынан қала сыртындағы жасырынды тауып, ішіне өз жазбаларыңды қалдырыңдар.', 124),
  ('trip-childhood-places', 'trip', 'Съездить в места детства одного из вас', 'Visit the place where one of you grew up', 'Балалық шақ өткен жерге бару', 'Показать свою школу, двор и любимое место и рассказать историю о каждом.', 'Show your school, your yard, and your favorite spot, with a story for each.', 'Мектепті, ауланы және сүйікті жерді көрсетіп, әрқайсысының хикаясын айту.', 128),
  ('trip-apiary', 'trip', 'Съездить на пасеку', 'Visit an apiary', 'Омартаға бару', 'Попробовать несколько сортов меда прямо из сот и выбрать свой.', 'Taste a few kinds of honey straight from the comb and pick your favorite.', 'Бал ұясынан бірнеше түрін татып көріп, өздеріңе ұнағанын таңдаңдар.', 132),
  ('trip-mountain-pass', 'trip', 'Проехать через горный перевал', 'Drive over a mountain pass', 'Тау асуынан көлікпен өту', 'Остановиться на самой высокой точке, выйти из машины и послушать тишину.', 'Stop at the highest point, step out of the car, and listen to the silence.', 'Ең биік нүктеде тоқтап, көліктен түсіп, тыныштықты тыңдаңдар.', 136),
  ('trip-autumn-colors', 'trip', 'Поехать смотреть на золотую осень', 'Go on a fall foliage drive', 'Алтын күзді тамашалауға бару', 'Выбрать ущелье или лес в разгар листопада и собрать букет из листьев.', 'Pick a gorge or forest at peak color and gather a bouquet of leaves.', 'Жапырақ түсер шақта шатқал не орман таңдап, жапырақтан шоқ құрастырыңдар.', 140),
  ('trip-trail-cleanup', 'trip', 'Убрать мусор на любимой тропе', 'Clean up a favorite hiking trail', 'Сүйікті соқпақты қоқыстан тазарту', 'Взять перчатки и мешки, а потом сфотографировать тропу чистой.', 'Bring gloves and bags, and photograph the trail once it''s clean.', 'Қолғап пен қап алып, тазартқаннан кейін соқпақты суретке түсіріңдер.', 144),
  ('trip-group-day-tour', 'trip', 'Съездить в однодневный тур с группой', 'Join a day tour with a group', 'Топпен бір күндік турға бару', 'Выбрать направление, куда сложно добраться самим, и познакомиться с попутчиками.', 'Pick a place that''s hard to reach on your own and get to know fellow travelers.', 'Өздерің жету қиын жерді таңдап, жолсеріктермен танысыңдар.', 148),
  ('trip-mountain-river-picnic', 'trip', 'Устроить пикник у горной реки', 'Picnic by a mountain river', 'Тау өзенінің жағасында пикник жасау', 'Охладить арбуз прямо в ледяной воде и посидеть босиком на камнях.', 'Chill a watermelon right in the icy water and sit barefoot on the rocks.', 'Қарбызды мұздай суға салып салқындатып, тастарда жалаңаяқ отырыңдар.', 152),
  ('trip-camel-ride', 'trip', 'Прокатиться на верблюде', 'Ride a camel', 'Түйеге міну', 'Найти хозяйство, где это разрешают, и узнать у хозяев, как зовут верблюда.', 'Find a farm that offers rides and ask the owners what the camel is called.', 'Мұндай мүмкіндік беретін шаруашылықты тауып, иелерінен түйенің атын сұраңдар.', 156),
  ('trip-steppe-photoshoot', 'trip', 'Устроить фотосессию в степи на закате', 'Do a sunset photo shoot in the steppe', 'Күн батарда далада фотосессия жасау', 'Взять штатив, светлую одежду и снимать в золотой час против солнца.', 'Bring a tripod and light-colored clothes, and shoot into the golden-hour sun.', 'Штатив пен ашық түсті киім алып, алтын сағатта күнге қарсы түсіріңдер.', 160)
insert into public.texts (key, lang, value) values
  ('n.meds.body', 'ru', '%1$s по расписанию. Отметь, когда примешь.'),
  ('n.meds.body', 'kk', 'Кесте бойынша %1$s. Қабылдағанда белгіле.'),
  ('n.meds.body', 'en', '%1$s as scheduled. Mark it once you have taken it.')
